package com.spai.portal.asset.domain;
import javax.persistence.*;
@Entity @Table(name="asset_category") public class AssetCategory {@Id private String id;@Column(name="stage_id",nullable=false)private Integer stageId;@Column(nullable=false)private String number;@Column(nullable=false)private String name;@Column(name="external_folder_id")private String externalFolderId;@Column(name="sort_order",nullable=false)private int sortOrder;public String getId(){return id;}public void setId(String id){this.id=id;}public Integer getStageId(){return stageId;}public void setStageId(Integer stageId){this.stageId=stageId;}public String getNumber(){return number;}public void setNumber(String number){this.number=number;}public String getName(){return name;}public void setName(String name){this.name=name;}public String getExternalFolderId(){return externalFolderId;}public void setExternalFolderId(String externalFolderId){this.externalFolderId=externalFolderId;}public int getSortOrder(){return sortOrder;}public void setSortOrder(int sortOrder){this.sortOrder=sortOrder;}}
